"""S3-T1: Codex TOML agents generated by tools/build.py (build and --codex-project).
Expected values come from the task brief (acceptance criteria 1-5), not from the code."""
import importlib.util
import json
import sys
import tomllib
from pathlib import Path

_s = importlib.util.spec_from_file_location("hv2", Path(__file__).resolve().parent / "hv2.py")
h = importlib.util.module_from_spec(_s)
sys.modules["hv2"] = h
_s.loader.exec_module(h)

KEYS = {"name", "model", "model_reasoning_effort", "description", "developer_instructions"}


def _build(src, *args):
    return h.run([h.PY, "-s", str(src / "tools" / "build.py"), *args], src)


def _proj(name="proj"):
    """(project dir named `name`, backup dir) in a fresh temp folder; .claude/agents exists."""
    root = h.fresh("cx")
    p = root / name
    (p / ".claude" / "agents").mkdir(parents=True)
    return p, root / "bk"


def _agent(p, fname, text):
    (p / ".claude" / "agents" / fname).write_bytes(text.encode("utf-8"))


def _cp(p, b):
    return _build(h.SRC, "--codex-project", str(p), "--backup", str(b))


def _snapshot(*roots):
    snap = {}
    for r in roots:
        if r.exists():
            for f in sorted(r.rglob("*")):
                snap[str(f)] = f.read_bytes() if f.is_file() else None
    return snap


def _toml(p, stem):
    return tomllib.loads((p / ".codex" / "agents" / f"{stem}.toml").read_text(encoding="utf-8"))


GOOD = "---\nname: alpha\ndescription: Does alpha\n---\nBody A\n"


# ---- criterion 1: global build ----
def test_global_build_writes_toml_for_every_manifest_agent():
    res = _build(h.SRC)
    assert res.rc == 0, res.all
    names = [a["name"] for a in json.loads((h.SRC / "harness" / "manifest.json").read_text(encoding="utf-8"))["agents"]]
    assert len(names) > 0
    d = h.SRC / "out" / "codex" / "agents"
    assert sorted(p.stem for p in d.glob("*.toml")) == sorted(names)
    assert not list(d.glob("*.md")), "old .md copies must be gone"
    for n in names:
        data = tomllib.loads((d / f"{n}.toml").read_text(encoding="utf-8"))
        assert set(data) == KEYS, (n, set(data))
        assert data["name"] == n
        assert data["model"] == "gpt-6-luna" and data["model_reasoning_effort"] == "medium"
        assert data["description"].strip()
        assert data["developer_instructions"].startswith(
            f"Generated from `harness/agents/{n}.md` by Harness v2 tools/build.py; edit the source, not this file.\n"
        ), data["developer_instructions"][:150]


# ---- criterion 2 and 4: fields, quoting, preamble, round trip ----
def test_project_basic_fields_and_preamble_without_skills():
    p, b = _proj()
    _agent(p, "alpha.md", GOOD)
    res = _cp(p, b)
    assert res.rc == 0, res.all
    d = _toml(p, "alpha")
    assert d == {
        "name": "alpha", "model": "gpt-6-luna", "model_reasoning_effort": "medium",
        "description": "Does alpha",
        "developer_instructions": "Generated from `.claude/agents/alpha.md` by Harness v2 tools/build.py; "
                                  "edit the source, not this file.\n\nBody A\n",
    }, d


def test_project_skills_line_when_frontmatter_has_skills():
    p, b = _proj()
    _agent(p, "alpha.md", "---\nname: alpha\ndescription: d\nskills:\n  - s-one\n  - s-two\n---\nBody\n")
    assert _cp(p, b).rc == 0
    di = _toml(p, "alpha")["developer_instructions"]
    assert di == ("Generated from `.claude/agents/alpha.md` by Harness v2 tools/build.py; edit the source, not this file.\n"
                  "Skills: s-one, s-two. Follow them when the task matches.\n\nBody\n"), repr(di)


def test_name_falls_back_to_file_stem_and_quoted_name_is_unquoted():
    p, b = _proj()
    _agent(p, "no-name.md", "---\ndescription: d1\n---\nB1\n")
    _agent(p, "file2.md", '---\nname: "quoted-name"\ndescription: d2\n---\nB2\n')
    _agent(p, "file3.md", "---\nname: 'single-q'\ndescription: d3\n---\nB3\n")
    res = _cp(p, b)
    assert res.rc == 0, res.all
    got = sorted(f.stem for f in (p / ".codex" / "agents").glob("*.toml"))
    assert got == ["no-name", "quoted-name", "single-q"], got
    assert _toml(p, "no-name")["name"] == "no-name"
    assert _toml(p, "quoted-name")["name"] == "quoted-name"
    assert _toml(p, "single-q")["name"] == "single-q"


def test_quoted_descriptions_are_decoded():
    p, b = _proj()
    _agent(p, "dq.md", '---\nname: dq\ndescription: "say \\"hi\\"\\tand \\u00e9 \\\\ end"\n---\nB\n')
    _agent(p, "sq.md", "---\nname: sq\ndescription: 'it''s ok: \"x\" \\n'\n---\nB\n")
    res = _cp(p, b)
    assert res.rc == 0, res.all
    assert _toml(p, "dq")["description"] == 'say "hi"\tand \u00e9 \\ end'
    # single-quoted: only '' becomes ', backslashes stay literal
    assert _toml(p, "sq")["description"] == 'it\'s ok: "x" \\n'


def test_body_roundtrip_crlf_special_chars_and_trim():
    body = ('Line "quoted" and \\backslash\\ and \\n literal\n'
            "tab\there\n"
            "ctl\x01\x1f\x7f end\n"
            "\n"
            "unicode: \u043f\u0440\u0438\u0432\u0435\u0442 \u00e9 \u4e2d\u6587 \U0001F600\n"
            "last line")
    raw = "---\r\nname: rt\r\ndescription: d\r\n---\r\n\r\n\r\n" + body.replace("\n", "\r\n") + "\r\n\r\n\r\n"
    p, b = _proj()
    _agent(p, "rt.md", raw)
    res = _cp(p, b)
    assert res.rc == 0, res.all
    di = _toml(p, "rt")["developer_instructions"]
    pre = "Generated from `.claude/agents/rt.md` by Harness v2 tools/build.py; edit the source, not this file.\n"
    assert di == pre + "\n" + body + "\n", repr(di)
    assert "\r" not in di


def test_description_with_control_chars_roundtrips():
    p, b = _proj()
    _agent(p, "c.md", '---\nname: c\ndescription: "a\\u0001b\\u007fc\\td"\n---\nB\n')
    assert _cp(p, b).rc == 0
    assert _toml(p, "c")["description"] == "a\x01b\x7fc\td"


def test_rerun_is_idempotent_and_output_is_utf8_lf():
    p, b = _proj()
    _agent(p, "alpha.md", GOOD)
    assert _cp(p, b).rc == 0
    f = p / ".codex" / "agents" / "alpha.toml"
    first = f.read_bytes()
    assert b"\r" not in first
    first.decode("utf-8")
    assert _cp(p, b).rc == 0  # overwritten file is copied to the backup, content is the same
    assert f.read_bytes() == first


# ---- criterion 3: stale, overwrite, backup ----
def test_stale_moved_overwritten_copied_nothing_deleted():
    p, b = _proj("myproj")
    _agent(p, "alpha.md", GOOD)
    dst = p / ".codex" / "agents"
    dst.mkdir(parents=True)
    (dst / "alpha.toml").write_bytes(b"old alpha content\n")
    (dst / "stale.toml").write_bytes(b"stale content\n")
    (dst / "notes.txt").write_bytes(b"not a toml\n")
    res = _cp(p, b)
    assert res.rc == 0, res.all
    keep = b / "myproj"
    assert (keep / "stale.toml").read_bytes() == b"stale content\n"       # moved
    assert not (dst / "stale.toml").exists()
    assert (keep / "alpha.toml").read_bytes() == b"old alpha content\n"   # copied before overwrite
    assert tomllib.loads((dst / "alpha.toml").read_text(encoding="utf-8"))["name"] == "alpha"
    assert (dst / "notes.txt").read_bytes() == b"not a toml\n"            # non-TOML untouched
    assert not (keep / "notes.txt").exists()
    assert sorted(f.name for f in keep.iterdir()) == ["alpha.toml", "stale.toml"]


def test_stale_match_uses_generated_name_not_source_file_name():
    p, b = _proj("pp")
    _agent(p, "file-x.md", "---\nname: real-name\ndescription: d\n---\nB\n")
    dst = p / ".codex" / "agents"
    dst.mkdir(parents=True)
    (dst / "file-x.toml").write_bytes(b"stale by stem\n")
    (dst / "real-name.toml").write_bytes(b"to overwrite\n")
    assert _cp(p, b).rc == 0
    keep = b / "pp"
    assert (keep / "file-x.toml").read_bytes() == b"stale by stem\n" and not (dst / "file-x.toml").exists()
    assert (keep / "real-name.toml").read_bytes() == b"to overwrite\n"
    assert _toml(p, "real-name")["name"] == "real-name"


def test_backup_clash_stops_before_anything_moves():
    p, b = _proj("pp")
    _agent(p, "alpha.md", GOOD)
    dst = p / ".codex" / "agents"
    dst.mkdir(parents=True)
    (dst / "alpha.toml").write_bytes(b"old alpha\n")
    (dst / "stale.toml").write_bytes(b"stale\n")
    keep = b / "pp"
    keep.mkdir(parents=True)
    (keep / "alpha.toml").write_bytes(b"already in backup\n")   # clash only on the overwritten file
    before = _snapshot(p, b)
    res = _cp(p, b)
    assert res.rc == 1, res.all
    assert _snapshot(p, b) == before, "stale file must not move and nothing may be written on clash"
    # clash on the stale file instead
    p2, b2 = _proj("pp")
    _agent(p2, "alpha.md", GOOD)
    d2 = p2 / ".codex" / "agents"
    d2.mkdir(parents=True)
    (d2 / "alpha.toml").write_bytes(b"old alpha\n")
    (d2 / "stale.toml").write_bytes(b"stale\n")
    (b2 / "pp").mkdir(parents=True)
    (b2 / "pp" / "stale.toml").write_bytes(b"older stale\n")
    before2 = _snapshot(p2, b2)
    res2 = _cp(p2, b2)
    assert res2.rc == 1, res2.all
    assert _snapshot(p2, b2) == before2


def test_backup_is_per_project_folder_name():
    pa, b = _proj("projA")
    _agent(pa, "alpha.md", GOOD)
    (pa / ".codex" / "agents").mkdir(parents=True)
    (pa / ".codex" / "agents" / "gone.toml").write_bytes(b"a\n")
    pb = b.parent / "projB"
    (pb / ".claude" / "agents").mkdir(parents=True)
    _agent(pb, "alpha.md", GOOD)
    (pb / ".codex" / "agents").mkdir(parents=True)
    (pb / ".codex" / "agents" / "gone.toml").write_bytes(b"b\n")
    assert _cp(pa, b).rc == 0
    assert _cp(pb, b).rc == 0  # same file name, different project folder: no clash
    assert (b / "projA" / "gone.toml").read_bytes() == b"a\n"
    assert (b / "projB" / "gone.toml").read_bytes() == b"b\n"


# ---- criterion 5: stop with exit 1 and no side effects ----
def _assert_stopped(p, b, res, before=None):
    assert res.rc == 1, res.all
    assert not (p / ".codex" / "agents" / "alpha.toml").exists(), "nothing may be written"
    if before is not None:
        assert _snapshot(p, b) == before, "tree changed on a stopped run"


def _with_stale(p):
    dst = p / ".codex" / "agents"
    dst.mkdir(parents=True)
    (dst / "stale.toml").write_bytes(b"stale\n")


def _stop_case(extra_files, expect_in_output=None):
    p, b = _proj()
    _agent(p, "alpha.md", GOOD)
    for f, t in extra_files:
        _agent(p, f, t)
    _with_stale(p)
    before = _snapshot(p, b)
    res = _cp(p, b)
    _assert_stopped(p, b, res, before)
    assert not b.exists() or not list(b.rglob("*")), "backup must stay empty"
    if expect_in_output:
        assert expect_in_output in res.all, res.all


def test_stops_on_missing_claude_agents_folder():
    root = h.fresh("cx")
    p = root / "proj"
    p.mkdir()
    res = _cp(p, root / "bk")
    assert res.rc == 1, res.all
    assert not (p / ".codex").exists() and not (root / "bk").exists()


def test_stops_when_a_file_has_no_frontmatter():
    _stop_case([("nofm.md", "just text, no frontmatter\n")], "nofm.md")


def test_stops_on_duplicate_names():
    _stop_case([("beta.md", "---\nname: alpha\ndescription: other\n---\nB\n")])
    # duplicate through fallback name vs explicit name
    _stop_case([("alpha2.md", "---\nname: alpha\ndescription: other\n---\nB\n")])


def test_stops_on_bad_name_characters():
    for bad in ("bad name", "bad/name", "bad:name"):
        _stop_case([("bad.md", f'---\nname: "{bad}"\ndescription: d\n---\nB\n')])


def test_stops_on_non_ascii_name_characters():
    # brief: allowed set is exactly [A-Za-z0-9_.-]; letters and digits outside ASCII are not allowed
    for bad in ("b\u00e9d", "\u0434\u0430", "a\u0663"):
        _stop_case([("bad.md", f'---\nname: "{bad}"\ndescription: d\n---\nB\n')])


def test_allowed_name_characters_pass():
    p, b = _proj()
    _agent(p, "x.md", "---\nname: Ab_9.z-Q\ndescription: d\n---\nB\n")
    res = _cp(p, b)
    assert res.rc == 0, res.all
    assert (p / ".codex" / "agents" / "Ab_9.z-Q.toml").is_file()


def test_stops_on_empty_or_block_marker_description():
    for desc_line in ("description:", "description: >", "description: |", "description: >-", "description: |+", 'description: ""'):
        _stop_case([("e.md", f"---\nname: e\n{desc_line}\n  continued text\n---\nB\n")])
    _stop_case([("e.md", "---\nname: e\n---\nB\n")])  # description missing


def test_stops_when_folder_has_no_md_files():
    p, b = _proj()
    (p / ".claude" / "agents" / "readme.txt").write_text("x", encoding="utf-8")
    _with_stale(p)
    before = _snapshot(p, b)
    res = _cp(p, b)
    assert res.rc == 1, res.all
    assert _snapshot(p, b) == before
    assert not b.exists()


def test_codex_project_without_backup_is_usage_error():
    p, _b = _proj()
    _agent(p, "alpha.md", GOOD)
    res = _build(h.SRC, "--codex-project", str(p))
    assert res.rc != 0 and res.rc != 0, res.all
    assert "--backup" in res.all, res.all
    assert not (p / ".codex").exists()


if __name__ == "__main__":
    sys.exit(h.run_all(globals()))
